// Golden dump: drives stimuli.txt into the ORIGINAL qr at N=8 and writes
// (done, r_out) once per stimulus line -> golden.txt. Generated by gen_vectors.py.
module tb;
  localparam N = 8, DW = 16;
  logic clk, reset_n, start, done;
  logic [N*N*DW-1:0] a_in, r_out;

  qr #(.N(N), .DW(DW)) dut
    (.clk(clk), .reset_n(reset_n), .start(start), .a_in(a_in),
     .done(done), .r_out(r_out));

  initial clk = 0;
  always #5 clk = ~clk;

  integer fin, fout, rc;
  string line_buf;
  logic s_st;
  logic [N*N*DW-1:0] s_a;

  initial begin
    start = 0; a_in = 0;
    reset_n = 0;
    repeat (4) @(negedge clk);
    reset_n = 1;
    fin = $fopen("stimuli.txt", "r");
    fout = $fopen("golden.txt", "w");
    if (fin == 0 || fout == 0) begin $display("ERROR: files"); $fatal(1); end
    while (!$feof(fin)) begin
      void'($fgets(line_buf, fin));
      if (line_buf.len() == 0) continue;
      rc = $sscanf(line_buf, "%h %h", s_st, s_a);
      if (rc != 2) continue;
      start = s_st; a_in = s_a;
      @(negedge clk);
      $fwrite(fout, "%h %h\n", done, r_out);
    end
    $fclose(fin); $fclose(fout);
    $display("GOLDEN_DONE");
    $display("PASS");
    $finish;
  end
endmodule
